const intake=$('🧠 Intake').first().json;
const rows=Array.isArray($input.first().json)?$input.first().json:($input.first().json.data||[]);
const s=rows[0]||{ niche:'', style:'', broll_source:'pexels', reference:'', platform:'youtube', pending_action:null };
const pending=s.pending_action||null;
const sys=`You are the expert YouTube/TikTok Shorts manager for a creator. Chat naturally and CONFIRM before creating.

Current settings:
- niche: "${s.niche||'(not set)'}"
- visual style: "${s.style||'(not set)'}"
- b-roll source: "${s.broll_source||'pexels'}" (pexels or pinterest)
- reference style/search for clips: "${s.reference||'(none)'}"
- platform: "${s.platform||'youtube'}"
- pending action: ${pending?JSON.stringify(pending):'(none)'}

Rules:
- Setting niche/style/platform, the b-roll source (pexels|pinterest), or a reference clip style => intent=set_config, fill the set_* fields.
- Asking to CREATE a short/video => intent=propose, action_type=video, fill topic (and script if pasted). Write a short reply describing the plan and ask them to reply 'yes'.
- Confirmation (yes/go/do it) with a pending action => intent=confirm.
- cancel => intent=cancel. Else intent=chat.
- If niche or style missing when they want to create, ask them to set it first (intent=chat).
Respond STRICT JSON only.`;
const usr=`User: "${intake.text}"
Return JSON: {
 "reply":"...",
 "intent":"set_config|propose|confirm|cancel|chat",
 "set_niche":"","set_style":"","set_broll_source":"","set_reference":"","set_platform":"",
 "action_type":"video|none","topic":"","script":""
}`;
return [{ json:{ chatId:intake.chatId, niche:s.niche||'', style:s.style||'', broll_source:s.broll_source||'pexels', reference:s.reference||'', platform:s.platform||'youtube', pending, requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.5, max_tokens:700 } } }];

const ctx=$('🧠 Manager Brain Prompt').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const mm=((($input.first().json.choices||[{}])[0].message||{}).content||'').match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const p=ctx.pending||{};
const action_type=(o.action_type&&o.action_type!=='none')?o.action_type:(p.action_type||'video');
return [{ json:{ chatId:ctx.chatId, niche:ctx.niche, style:ctx.style, broll_source:ctx.broll_source, reference:ctx.reference, platform:ctx.platform, reply:o.reply||'Okay!', intent:o.intent||'chat', set_niche:o.set_niche||'', set_style:o.set_style||'', set_broll_source:o.set_broll_source||'', set_reference:o.set_reference||'', set_platform:o.set_platform||'', action_type, topic:o.topic||p.topic||'', script:o.script||p.script||'' } }];

const m=$json;
const sys=`You are a Shorts scriptwriter AND editor for the niche \"${m.niche}\". Visual style: \"${m.style}\". Write a high-retention vertical short and self-review for hook + pacing. Respond STRICT JSON only.`;
let usr;
if(m.script){ usr=`Use THIS script (keep wording, split into 4 scenes):\n\"${m.script}\"\nReturn JSON: {\"caption\":\"title + hashtags\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"<=6 words\",\"broll_keyword\":\"simple visual search term\"}]}`; }
else { usr=`Topic: ${m.topic}\nWrite a 4-scene short: hook -> value -> payoff -> CTA, 80-120 words.\nReturn JSON: {\"caption\":\"title + hashtags\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"<=6 words\",\"broll_keyword\":\"simple visual search term\"}]}`; }
return [{ json:{ ...m, requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.85, max_tokens:1300 } } }];

const m=$('🧩 Prep Action').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const mm=((($input.first().json.choices||[{}])[0].message||{}).content||'').match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const scenes=(o.scenes||[]).slice(0,6).map((s,i)=>({ idx:i, narration:s.narration||'', on_screen_text:s.on_screen_text||'', broll_keyword:s.broll_keyword||m.topic }));
const caption=o.caption||m.topic;
// query: reference style overrides keyword when set
return scenes.map(s=>({ json:{ chatId:m.chatId, niche:m.niche, style:m.style, broll_source:m.broll_source, reference:m.reference, platform:m.platform, topic:m.topic, job:m.job, caption, idx:s.idx, narration:s.narration, on_screen_text:s.on_screen_text, broll_keyword:s.broll_keyword, query:(m.reference?m.reference:s.broll_keyword) } }));

const base=$('🎬 Split Scenes').item.json;
let html=$json.data; if(typeof html!=='string') html=JSON.stringify($json);
// extract Pinterest video mp4 URLs from the page payload
const re=/https:\/\/v[0-9a-z]*\.pinimg\.com\/[^\"\\ ]+\.mp4/g;
const found=[...new Set((html.match(re)||[]))];
// prefer 720p variants if present
found.sort((a,b)=>((b.includes('720')?1:0)-(a.includes('720')?1:0)));
const clip=found[0]||'';
return [{ json:{ ...base, clip_url:clip, broll_used:'pinterest' } }];

const base=$('🎬 Split Scenes').item.json;
const r=$json;let url='';
try{ const v=r.videos||[]; if(v.length){ const f=v[0].video_files||[]; const port=f.filter(x=>x.height>=x.width); const pool=port.length?port:f; pool.sort((a,b)=>(b.height||0)-(a.height||0)); url=(pool[0]||{}).link||''; } }catch(e){}
return [{ json:{ ...base, clip_url:url, broll_used:'pexels' } }];

// run once: gather all scenes (sorted by idx), build ffmpeg job
const items=$input.all().map(i=>i.json);
items.sort((a,b)=>(a.idx||0)-(b.idx||0));
const m=$('🧩 Prep Action').first().json;
const KEY=$vars.OPENAI_API_KEY;
const FONT=$vars.FFMPEG_FONT||'/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf';
const voice=$vars.OPENAI_TTS_VOICE||'onyx';
const dir='/tmp/'+m.job;const b64=(s)=>Buffer.from(String(s||''),'utf8').toString('base64');
const L=['set -e','export DIR='+dir,'mkdir -p $DIR','cd $DIR'];const list=[];
items.forEach((s,i)=>{
  const tts=JSON.stringify({model:'tts-1-hd',voice:voice,input:s.narration||m.topic});
  L.push(`echo \"${b64(tts)}\" | base64 -d > tts_${i}.json`);
  L.push(`curl -s https://api.openai.com/v1/audio/speech -H \"Authorization: Bearer ${KEY}\" -H \"Content-Type: application/json\" --data @tts_${i}.json -o voice_${i}.mp3`);
  L.push(`echo \"${b64(s.on_screen_text)}\" | base64 -d > cap_${i}.txt`);
  L.push(`D=$(ffprobe -v error -show_entries format=duration -of csv=p=0 voice_${i}.mp3)`);
  const hasClip = s.clip_url && s.clip_url.length>5;
  if(hasClip) L.push(`curl -sL \"${s.clip_url}\" -o src_${i}.mp4 || true`);
  const vf=`scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,drawtext=fontfile=${FONT}:textfile=cap_${i}.txt:fontcolor=white:fontsize=64:box=1:boxcolor=black@0.55:boxborderw=26:x=(w-text_w)/2:y=h-560`;
  const input = hasClip ? `-stream_loop -1 -t $D -i src_${i}.mp4` : `-f lavfi -t $D -i color=c=0x111418:s=1080x1920`;
  L.push(`ffmpeg -y ${input} -i voice_${i}.mp3 -vf \"${vf}\" -map 0:v -map 1:a -r 30 -c:v libx264 -preset veryfast -pix_fmt yuv420p -c:a aac -shortest scene_${i}.mp4`);
  list.push(`file 'scene_${i}.mp4'`);
});
L.push(`printf \"${list.join('\\n')}\\n\" > list.txt`);
L.push(`ffmpeg -y -f concat -safe 0 -i list.txt -c copy ${dir}/final.mp4`);
L.push(`echo DONE ${dir}/final.mp4`);
const caption=(items[0]&&items[0].caption)||m.topic;
return [{ json:{ chatId:m.chatId, niche:m.niche, style:m.style, platform:m.platform, topic:m.topic, job:m.job, caption, broll_used:(items[0]&&items[0].broll_used)||m.broll_source, outPath:dir+'/final.mp4', ffmpegScript:L.join('\n') } }];

const m=$('🎞️ Build FFmpeg Job').first().json;
const publicUrl=`${$vars.SUPABASE_URL}/storage/v1/object/public/videos/${m.job}.mp4`;
const plat=m.platform||'youtube';
const profiles=[];
if(plat==='youtube'||plat==='both'){ if($vars.BUFFER_PROFILE_ID_YOUTUBE) profiles.push($vars.BUFFER_PROFILE_ID_YOUTUBE); }
if(plat==='tiktok'||plat==='both'){ if($vars.BUFFER_PROFILE_ID_TIKTOK) profiles.push($vars.BUFFER_PROFILE_ID_TIKTOK); }
const parts=[];profiles.forEach(p=>parts.push('profile_ids[]='+encodeURIComponent(p)));parts.push('text='+encodeURIComponent(m.caption||m.topic));parts.push('media[video]='+encodeURIComponent(publicUrl));parts.push('now=true');
return [{ json:{ chatId:m.chatId, niche:m.niche, style:m.style, platform:plat, topic:m.topic, caption:m.caption, broll_used:m.broll_used, video_url:publicUrl, bufferBody:parts.join('&') } }];

